import com.koios.client.arpg.*;import com.koios.client.graphic.*;import com.koios.client.cache.Decompressor;import com.koios.client.stream.StreamLoader;import java.awt.event.*;import java.nio.file.*;import java.awt.*;import java.awt.image.*;import java.io.*;import javax.imageio.ImageIO;
/** Account isolation, exact modifiers, duplicate confirmation, reserved inputs and native UI layout. */
public final class InputBindingsCheck {
 static int checks;static void check(boolean v,String message){checks++;if(!v)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{
 Path dir=Files.createTempDirectory(Paths.get("build"),"controls-check-");InputBindings bindings=new InputBindings(dir,"QA Player");check(bindings.matchKey(KeyEvent.VK_Q,0)==0,"Defaults Q");check(bindings.matchKey(KeyEvent.VK_W,0)==1,"Defaults W");check(bindings.matchKey(KeyEvent.VK_E,0)==2,"Defaults E");
 for(int code:new int[]{KeyEvent.VK_ENTER,KeyEvent.VK_ESCAPE,KeyEvent.VK_SHIFT,KeyEvent.VK_CONTROL,KeyEvent.VK_ALT,KeyEvent.VK_META,KeyEvent.VK_ALT_GRAPH})check(InputBindings.key(code,0)==null,"Reserved or modifier-only input "+code);
 check(bindings.assign(1,InputBindings.key(KeyEvent.VK_Q,0),false)==0,"Reports duplicate");check(bindings.matchKey(KeyEvent.VK_W,0)==1,"Conflict does not mutate");check(bindings.assign(1,InputBindings.key(KeyEvent.VK_Q,0),true)==-1,"Explicit replacement");check(bindings.get(0)==null&&bindings.matchKey(KeyEvent.VK_Q,0)==1,"Only replaced slot cleared");
 int mods=InputEvent.CTRL_DOWN_MASK|InputEvent.SHIFT_DOWN_MASK;bindings.assign(0,InputBindings.key(KeyEvent.VK_R,mods),false);check(bindings.matchKey(KeyEvent.VK_R,mods)==0,"Keyboard chord");check(bindings.matchKey(KeyEvent.VK_R,InputEvent.CTRL_DOWN_MASK)==-1,"Exact modifier match");for(int button=1;button<=20;button++){bindings.assign(2,InputBindings.mouse(button,InputEvent.ALT_DOWN_MASK),false);check(bindings.matchMouse(button,InputEvent.ALT_DOWN_MASK|InputEvent.BUTTON1_DOWN_MASK)==2,"All AWT buttons and stripped button masks "+button);check(bindings.matchMouse(button,0)==-1,"Mouse chord requires modifier "+button);}check(InputBindings.mouse(0,0)==null&&InputBindings.mouse(21,0)==null,"AWT button bounds");
 bindings.save();InputBindings restored=new InputBindings(dir,"qa PLAYER");for(int slot=0;slot<3;slot++)check(bindings.get(slot)==null?restored.get(slot)==null:bindings.get(slot).equals(restored.get(slot)),"Account persistence "+slot);InputBindings other=new InputBindings(dir,"Other");check(other.matchKey(KeyEvent.VK_Q,0)==0,"Other account isolated");InputBindings slash=new InputBindings(dir,"a/b");slash.clear(0);slash.save();check(new InputBindings(dir,"a_b").get(0)!=null,"Filename encoding avoids sanitize collisions");
 ControlsPanel panel=new ControlsPanel(restored);panel.beginCapture(0);check(panel.captureKey(KeyEvent.VK_ENTER,0)&&panel.isCapturing(),"Enter rejected without leaving capture");check(panel.captureKey(KeyEvent.VK_CONTROL,InputEvent.CTRL_DOWN_MASK)&&panel.isCapturing(),"Modifier waits for main key");panel.captureKey(KeyEvent.VK_Q,0);check(panel.hasConflict(),"Panel conflict awaiting explicit choice");panel.focusLost();check(!panel.isCapturing()&&!panel.hasConflict(),"Focus loss cancels pending");check(restored.get(0).code==KeyEvent.VK_R,"Focus cancellation no mutation");panel.beginCapture(0);panel.captureKey(KeyEvent.VK_Q,0);panel.confirmReplace();check(restored.get(1)==null&&restored.matchKey(KeyEvent.VK_Q,0)==0,"Confirmed UI replacement");panel.beginCapture(2);panel.captureMouse(4,mods);check(!panel.isCapturing()&&restored.matchMouse(4,mods)==2,"Side mouse capture");panel.beginCapture(0);panel.captureKey(KeyEvent.VK_ESCAPE,0);check(!panel.isCapturing(),"Escape cancels capture");check(!panel.captureKey(KeyEvent.VK_Z,0),"No capture outside waiting");panel.click(30,280);check(restored.matchKey(KeyEvent.VK_Q,0)==0&&restored.matchKey(KeyEvent.VK_W,0)==1,"Reset button");panel.click(420,84);check(restored.get(0)==null,"Clear row button");check(new InputBindings(dir,"QA Player").get(0)==null,"Clear persisted");
 Path corrupt=Files.createDirectory(dir.resolve("corrupt"));Files.write(corrupt.resolve("626164.properties"),java.util.Arrays.asList("version=1","slot.0=key,10,0","slot.1=key,81,0","slot.2=key,81,0"));InputBindings bad=new InputBindings(corrupt,"bad");check(bad.get(0)==null,"Reserved Enter rejected on disk");check(bad.matchKey(KeyEvent.VK_Q,0)==1&&bad.get(2)==null,"On-disk duplicate deterministically removed");Path blocked=Files.createFile(dir.resolve("blocked"));InputBindings unsaved=new InputBindings(blocked,"bad");ControlsPanel failed=new ControlsPanel(unsaved);failed.beginCapture(0);failed.captureKey(KeyEvent.VK_R,0);check(unsaved.matchKey(KeyEvent.VK_R,0)==0&&!failed.isCapturing()&&failed.status().contains("Could not save"),"Persistence failure keeps session binding and honest message");
 try(RandomAccessFile data=new RandomAccessFile("../koios-cache/main_file_cache.dat","r");RandomAccessFile index=new RandomAccessFile("../koios-cache/main_file_cache.idx0","r")){TextDrawingArea font=new TextDrawingArea(false,"p12_full",new StreamLoader(new Decompressor(data,index,1).decompress(1)));BufferedImage preview=new BufferedImage(1536,334,BufferedImage.TYPE_INT_RGB);Graphics2D graphics=preview.createGraphics();for(int state=0;state<3;state++){if(state==1)panel.beginCapture(0);if(state==2)panel.captureKey(KeyEvent.VK_W,0);BufferedImage image=new BufferedImage(512,334,BufferedImage.TYPE_INT_RGB);int[] pixels=((DataBufferInt)image.getRaster().getDataBuffer()).getData();java.util.Arrays.fill(pixels,0x0D141A);DrawingArea.initDrawingArea(334,512,pixels);panel.draw(font);graphics.drawImage(image,state*512,0,null);}graphics.dispose();ImageIO.write(preview,"png",new File("build/controls-panel.png"));}
 System.out.println("Passed "+checks+" controls model/capture/persistence checks.");
 }
}

